 SET search_path TO ''
AS $function$
  select array['scopritevi', 'confrontatevi', 'ridete', 'quanto_mi_conosci', 'rivivete', 'e_se']::text[];
$function$;

-- private.game_v2_fill(template text, source jsonb)
CREATE OR REPLACE FUNCTION private.game_v2_fill(template text, source jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select replace(replace(replace(replace(template,
    '{title}', coalesce(source->>'title', '')), '{date}', coalesce(source->>'date', '')),
    '{when}', coalesce(source->>'when', '')), '{previous_question}', coalesce(source->>'previous_question', ''));
$function$;

