-- private.game_v2_push_event(kind text, couple uuid, recipient text, sender text, reference text)
CREATE OR REPLACE FUNCTION private.game_v2_push_event(kind text, couple uuid, recipient text, sender text, reference text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
