-- private.game_v2_question_sealed(target_question_id uuid, question_origin text, question_author text, caller_role text)
CREATE OR REPLACE FUNCTION private.game_v2_question_sealed(target_question_id uuid, question_origin text, question_author text, caller_role text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select question_origin = 'weekly' and question_author <> caller_role
    and not exists (select 1 from public.game_session_items i where i.source_question_id = target_question_id);
$function$;

-- private.game_v2_recipe_candidates(target_family text, target_adapter text, source_kind text, sources jsonb, at_time timestamp with time zone)
CREATE OR REPLACE FUNCTION private.game_v2_recipe_candidates(target_family text, target_adapter text, source_kind text, sources jsonb, at_time timestamp with time zone)
 RETURNS SETOF private.game_v2_candidate
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select ('recipe:' || r.id || ':' || source_kind || ':' || (s->>'id')), r.family, r.mechanic, r.answer_kind,
    private.game_v2_fill(r.question_text, s), null::text, r.options, r.depth, r.topic, source_kind, s->>'id',
    r.id, r.version, null::uuid, null::integer,
    jsonb_build_object('kind', r.adapter, 'kind_label', private.game_v2_fill(r.kind_label, s),
      'source_type', source_kind, 'source_id', s->>'id', 'title', s->>'title', 'when', coalesce(s->>'when', s->>'date'),
      'recipe_id', r.id, 'recipe_version', r.version, 'captured_at', at_time),
    r.cooldown_class, 70 + 2 * (r.depth - 1), null::integer, null::boolean, null::timestamptz
  from jsonb_array_elements(coalesce(sources, '[]'::jsonb)) s
  join public.game_v2_recipes r on r.adapter = target_adapter and r.active
    and (target_family = 'per_voi' or r.family = target_family);
$function$;

-- private.game_v2_render_options(raw jsonb, subject text)
CREATE OR REPLACE FUNCTION private.game_v2_render_options(raw jsonb, subject text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(to_jsonb(private.game_v2_render(o.value, subject)) order by o.ordinality), '[]'::jsonb)
  from jsonb_array_elements_text(raw) with ordinality o;
$function$;

-- private.game_v2_render(template text, subject text)
CREATE OR REPLACE FUNCTION private.game_v2_render(template text, subject text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select replace(replace(replace(template, '{subject}', coalesce(private.game_v2_role_label(subject), '{subject}')),
    '{francesco}', 'Francesco'), '{beatrice}', 'Bea');
$function$;

-- private.game_v2_role_label(target_role text)
CREATE OR REPLACE FUNCTION private.game_v2_role_label(target_role text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case target_role when 'francesco' then 'Francesco' when 'beatrice' then 'Bea' end;
$function$;

-- private.game_v2_scored_candidates(target_couple uuid, target_family text, at_time timestamp with time zone, round_ordinal integer)
CREATE OR REPLACE FUNCTION private.game_v2_scored_candidates(target_couple uuid, target_family text, at_time timestamp with time zone, round_ordinal integer)
 RETURNS SETOF private.game_v2_candidate
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with hist as (
    select i.fingerprint, i.recipe_id, i.source_type, i.source_ref, i.topic, s.started_at
    from public.game_session_items i join public.game_sessions s on s.id = i.session_id
    where s.couple_id = target_couple and s.engine_version = 2
  )
  select c.candidate_key, c.family, c.mechanic, c.answer_kind, c.question_text, c.predict_text, c.options,
    c.depth, c.topic, c.source_type, c.source_ref, c.recipe_id, c.recipe_version, c.source_question_id,
    c.source_version, c.context, c.cooldown_class, c.base_score,
    c.base_score
      + (('x' || substr(md5(target_couple::text || ':' || c.candidate_key || ':' || round_ordinal::text), 1, 2))::bit(8)::integer % 12)
      - case when h.last_topic > at_time - make_interval(days => cd.topic_days) then 15 else 0 end,
    coalesce(h.last_exact > at_time - make_interval(days => cd.item_days), false)
      or coalesce(c.recipe_id is not null and h.last_recipe > at_time - make_interval(days => cd.recipe_days), false)
      or coalesce(h.last_source > at_time - make_interval(days => cd.source_days), false),
    greatest(h.last_exact, h.last_recipe, h.last_source)
  from private.game_v2_candidates(target_couple, target_family, at_time) c
  join public.game_v2_cooldowns cd on cd.cooldown_class = c.cooldown_class
  cross join lateral (
    select max(hist.started_at) filter (where hist.fingerprint = c.candidate_key) as last_exact,
      max(hist.started_at) filter (where c.recipe_id is not null and hist.recipe_id = c.recipe_id) as last_recipe,
      max(hist.started_at) filter (where hist.source_type = c.source_type and hist.source_ref = c.source_ref) as last_source,
      max(hist.started_at) filter (where hist.topic = c.topic) as last_topic
    from hist
  ) h;
$function$;

-- private.game_v2_select_items(target_couple uuid, target_family text, at_time timestamp with time zone, round_ordinal integer)
CREATE OR REPLACE FUNCTION private.game_v2_select_items(target_couple uuid, target_family text, at_time timestamp with time zone, round_ordinal integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  picked jsonb := '[]'::jsonb; keys text[] := '{}'; fams text[] := '{}'; topics text[] := '{}';
  sources text[] := '{}'; n_custom integer := 0; n_context integer := 0; n_pred integer := 0;
  n_deep integer := 0; n_light integer := 0;
  pass integer; seed integer; r private.game_v2_candidate;
  per_voi boolean := target_family = 'per_voi';
  fam_cap integer := case when target_family = 'per_voi' then 2 else 5 end;
begin
  for pass in 0..3 loop
    for seed in 1..3 loop
      exit when jsonb_array_length(picked) >= 5;
      continue when pass > 0 and seed > 1;
      continue when pass = 0 and not per_voi and seed < 3;
      for r in
        select * from private.game_v2_scored_candidates(target_couple, target_family, at_time, round_ordinal) c
        where (pass >= 2 or not c.cooled)
          and (pass <> 0 or (seed = 1 and c.source_type = 'couple_custom' and c.base_score >= 85)
                          or (seed = 2 and c.mechanic = 'prediction')
                          or (seed = 3 and c.depth = 1))
        order by case when pass >= 2 then c.last_played end asc nulls first, c.score desc, c.candidate_key
      loop
        exit when jsonb_array_length(picked) >= 5;
        continue when r.candidate_key = any (keys);
        continue when r.source_type <> 'curated' and (r.source_type || ':' || r.source_ref) = any (sources);
        continue when per_voi and r.mechanic = 'prediction' and n_pred >= 2;
        continue when per_voi and r.source_type = 'couple_custom' and n_custom >= 2;
        continue when r.source_type not in ('curated', 'couple_custom') and n_context >= case when per_voi then 2 else 3 end;
        if pass < 3 then
          continue when r.topic = any (topics);
          continue when (select count(*) from unnest(fams) f where f = r.family) >= fam_cap;
          continue when r.depth = 3 and n_deep >= 2;
          continue when r.depth = 1 and n_light >= 2;
        end if;
        picked := picked || jsonb_build_array(to_jsonb(r));
        keys := keys || r.candidate_key; fams := fams || r.family; topics := topics || r.topic;
        sources := sources || (r.source_type || ':' || r.source_ref);
        n_custom := n_custom + (r.source_type = 'couple_custom')::integer;
        n_context := n_context + (r.source_type not in ('curated', 'couple_custom'))::integer;
        n_pred := n_pred + (r.mechanic = 'prediction')::integer;
        n_deep := n_deep + (r.depth = 3)::integer;
        n_light := n_light + (r.depth = 1)::integer;
        exit when pass = 0;
      end loop;
    end loop;
  end loop;
  -- Lighter opening, meaningful middle, strongest later.
  return coalesce((select jsonb_agg(e order by (e->>'depth')::integer, (e->>'score')::integer, e->>'candidate_key')
    from jsonb_array_elements(picked) e), '[]'::jsonb);
end;
$function$;

-- private.game_v2_session_summary(target_session_id uuid, current_couple uuid, caller_role text)
CREATE OR REPLACE FUNCTION private.game_v2_session_summary(target_session_id uuid, current_couple uuid, caller_role text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'id', s.id, 'game_family', s.game_family, 'engine_version', s.engine_version,
    'started_by_role', s.started_by_role, 'started_at', s.started_at, 'completed_at', s.completed_at,
    'my_complete', mine.completed_at is not null,
    'partner_complete', partner.completed_at is not null,
    'reveal_ready', s.completed_at is not null,
    'my_reveal_seen_at', mine.reveal_seen_at,
    'item_count', (select count(*) from public.game_session_items i where i.session_id = s.id),
    'my_answered_count', (select count(*) from public.game_session_items i
      join public.game_session_answers a on a.item_id = i.id and a.actor_role = caller_role
      where i.session_id = s.id))
  from public.game_sessions s
  join public.game_session_sides mine on mine.session_id = s.id and mine.actor_role = caller_role
  join public.game_session_sides partner on partner.session_id = s.id and partner.actor_role <> caller_role
  where s.id = target_session_id and s.couple_id = current_couple;
$function$;

-- private.game_v2_valid_families(raw_families text[], target_kind text)
CREATE OR REPLACE FUNCTION private.game_v2_valid_families(raw_families text[], target_kind text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare cleaned text[];
begin
  if raw_families is null or cardinality(raw_families) = 0 then
    raise exception using errcode = '22023', message = 'invalid families';
  end if;
  select coalesce(array_agg(f order by array_position(private.game_v2_families(), f)), '{}')
    into cleaned from (select distinct unnest(raw_families) f) x;
  if not cleaned <@ private.game_v2_families() or cardinality(cleaned) = 0 then
    raise exception using errcode = '22023', message = 'invalid families';
  end if;
  if 'quanto_mi_conosci' = any (cleaned) and target_kind <> 'choice' then
    raise exception using errcode = '22023', message = 'prediction needs choices';
  end if;
  return cleaned;
end;
$function$;

-- private.game_v2_week_bounds(at_time timestamp with time zone, OUT starts_at timestamp with time zone, OUT ends_at timestamp with time zone)
CREATE OR REPLACE FUNCTION private.game_v2_week_bounds(at_time timestamp with time zone, OUT starts_at timestamp with time zone, OUT ends_at timestamp with time zone)
 RETURNS record
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select (private.game_v2_week_start(at_time)::timestamp at time zone 'Europe/Rome'),
         ((private.game_v2_week_start(at_time) + 7)::timestamp at time zone 'Europe/Rome');
$function$;

-- private.game_v2_week_limits()
CREATE OR REPLACE FUNCTION private.game_v2_week_limits()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object('per_voi', 1, 'free', 2, 'total', 3, 'open', 3);
$function$;

-- private.game_v2_week_start(at_time timestamp with time zone)
CREATE OR REPLACE FUNCTION private.game_v2_week_start(at_time timestamp with time zone)
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select date_trunc('week', at_time at time zone 'Europe/Rome')::date;
$function$;

-- private.game_v2_week_usage(current_couple uuid, at_time timestamp with time zone)
CREATE OR REPLACE FUNCTION private.game_v2_week_usage(current_couple uuid, at_time timestamp with time zone)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with b as (
    select * from private.game_v2_week_bounds(at_time)
  ), lim as (
    select private.game_v2_week_limits() l
  ), wk as (
    select s.id, s.game_family, s.started_at, s.completed_at
    from public.game_sessions s, b
    where s.couple_id = current_couple and s.engine_version = 2
      and s.started_at >= b.starts_at and s.started_at < b.ends_at
  ), counts as (
    select count(*) filter (where game_family = 'per_voi')::integer per_voi_used,
           count(*) filter (where game_family <> 'per_voi')::integer free_used
    from wk
  ), open_rounds as (
    select count(*)::integer open_count from public.game_sessions s
    where s.couple_id = current_couple and s.engine_version = 2 and s.completed_at is null
  )
  select jsonb_build_object(
    'week_start', private.game_v2_week_start(at_time),
    'resets_on', private.game_v2_week_start(at_time) + 7,
    'per_voi_used', least(c.per_voi_used, (lim.l->>'per_voi')::integer),
    'per_voi_limit', (lim.l->>'per_voi')::integer,
    'free_used', least(c.free_used, (lim.l->>'free')::integer),
    'free_limit', (lim.l->>'free')::integer,
    'used', least(c.per_voi_used, (lim.l->>'per_voi')::integer) + least(c.free_used, (lim.l->>'free')::integer),
    'limit', (lim.l->>'total')::integer,
    'per_voi_available', c.per_voi_used < (lim.l->>'per_voi')::integer,
    'free_available', c.free_used < (lim.l->>'free')::integer,
    'open_count', o.open_count,
    'open_limit', (lim.l->>'open')::integer,
    -- Latest round of each mode started this week: lets the hub show a
    -- played mode as played instead of inviting an immediate repeat.
    'families', coalesce((
      select jsonb_object_agg(x.game_family, jsonb_build_object('session_id', x.id,
        'completed', x.completed_at is not null))
      from (select distinct on (game_family) id, game_family, completed_at from wk
            order by game_family, started_at desc, id desc) x), '{}'::jsonb)
  ) from counts c, lim, open_rounds o;
$function$;

-- private.game_v2_weekly_role(week_start date)
CREATE OR REPLACE FUNCTION private.game_v2_weekly_role(week_start date)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case when ((((week_start - date '2026-09-28') / 7) % 2) + 2) % 2 = 0
    then 'francesco' else 'beatrice' end;
$function$;

-- private.game_v2_weekly_state(current_couple uuid, caller_role text, at_time timestamp with time zone)
CREATE OR REPLACE FUNCTION private.game_v2_weekly_state(current_couple uuid, caller_role text, at_time timestamp with time zone)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with w as (
    select private.game_v2_week_start(at_time) as week_start
  ), q as (
    select cq.* from public.couple_questions cq, w
    where cq.couple_id = current_couple and cq.origin = 'weekly' and cq.week_start = w.week_start
  )
  select jsonb_build_object(
    'week_start', w.week_start,
    'next_unlock', w.week_start + 7,
    'assigned_role', private.game_v2_weekly_role(w.week_start),
    'next_role', private.game_v2_weekly_role(w.week_start + 7),
    'my_turn', private.game_v2_weekly_role(w.week_start) = caller_role,
    'created', q.id is not null,
    'created_by_me', q.id is not null and q.author_role = caller_role,
    'partner_left_question', q.id is not null and q.author_role <> caller_role,
    'created_at', q.created_at,
    'my_question', case when q.author_role = caller_role then jsonb_build_object(
      'id', q.id, 'question_text', q.question_text, 'answer_kind', q.answer_kind,
      'options', q.options, 'families', to_jsonb(q.families), 'archived', q.archived_at is not null) end
  ) from w left join q on true;
$function$;

-- private.game_v2_when_label(d date, at_date date)
CREATE OR REPLACE FUNCTION private.game_v2_when_label(d date, at_date date)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case when extract(month from d) in (4, 8) then 'ad ' else 'a ' end || private.game_v2_month_name(d)
    || case when extract(year from d) <> extract(year from at_date) then ' ' || extract(year from d)::integer::text else '' end;
$function$;

-- private.living_provenance_guard_update()
CREATE OR REPLACE FUNCTION private.living_provenance_guard_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.id <> old.id or new.couple_id <> old.couple_id
     or new.source_kind <> old.source_kind or new.source_ref <> old.source_ref
     or new.source_title is distinct from old.source_title or new.source_date is distinct from old.source_date
     or new.target_kind <> old.target_kind or new.target_ref <> old.target_ref
     or new.target_moment_id is distinct from old.target_moment_id
     or new.linked_by_role <> old.linked_by_role or new.created_at <> old.created_at
     or (new.source_event_completion_id is distinct from old.source_event_completion_id and new.source_event_completion_id is not null)
     or (new.source_bucket_item_id is distinct from old.source_bucket_item_id and new.source_bucket_item_id is not null)
  then
    raise exception using errcode = '42501', message = 'living_provenance_immutable';
  end if;
  return new;
end;
$function$;

-- private.m11a_actor_locked()
CREATE OR REPLACE FUNCTION private.m11a_actor_locked()
 RETURNS TABLE(caller_couple uuid, caller_role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;
  return query
    select p.couple_id, p.role from public.profiles p
    where p.id = auth.uid() and p.couple_id is not null
      and p.role in ('francesco', 'beatrice') for share;
  if not found then
    raise exception using errcode = '42501', message = 'couple membership required';
  end if;
end;
$function$;

-- private.m11a_actor()
CREATE OR REPLACE FUNCTION private.m11a_actor()
 RETURNS TABLE(caller_couple uuid, caller_role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;
  return query
    select p.couple_id, p.role from public.profiles p
    where p.id = auth.uid() and p.couple_id is not null
      and p.role in ('francesco', 'beatrice');
  if not found then
    raise exception using errcode = '42501', message = 'couple membership required';
