$function$;

-- private.m11a_session_state(target_session_id uuid, current_couple uuid, caller_role text)
CREATE OR REPLACE FUNCTION private.m11a_session_state(target_session_id uuid, current_couple uuid, caller_role text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'id', s.id, 'couple_id', s.couple_id, 'game_family', s.game_family,
    'content_source', s.content_source, 'started_by_role', s.started_by_role,
    'started_at', s.started_at, 'completed_at', s.completed_at,
    'engine_version', s.engine_version, 'subject_heavy_role', s.subject_heavy_role,
    'my_role', caller_role,
    'my_complete', mine.completed_at is not null, 'my_completed_at', mine.completed_at,
    'partner_complete', partner.completed_at is not null, 'partner_completed_at', partner.completed_at,
    'reveal_ready', s.completed_at is not null, 'my_reveal_seen_at', mine.reveal_seen_at,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', i.id, 'position', i.position, 'question_text', i.question_text,
        'answer_kind', i.answer_kind, 'options', i.options,
        'source_question_id', i.source_question_id, 'source_version', i.source_version,
        'mechanic', i.mechanic, 'family', coalesce(i.family, s.game_family),
        'subject_role', i.subject_role, 'predict_text', i.predict_text,
        'my_item_role', case when i.mechanic <> 'prediction' then 'mutual'
          when i.subject_role = caller_role then 'subject' else 'predictor' end,
        'my_prompt', case when i.mechanic = 'prediction' and i.subject_role <> caller_role
          then i.predict_text else i.question_text end,
        'source_type', i.source_type, 'depth', i.depth, 'context', i.context,
        'my_answer_text', a.answer_text, 'my_answer_index', a.answer_index,
        'partner_answer_text', case when s.completed_at is not null then pa.answer_text end,
        'partner_answer_index', case when s.completed_at is not null then pa.answer_index end,
        'prediction_matched', case when s.completed_at is not null and i.mechanic = 'prediction'
          and a.answer_index is not null and pa.answer_index is not null
          then a.answer_index = pa.answer_index end,
        'previous', case when s.completed_at is not null and i.context->>'kind' = 'longitudinal' then (
          select jsonb_build_object('played_at', ps.started_at,
            'my_answer_text', pma.answer_text, 'partner_answer_text', ppa.answer_text)
          from public.game_session_items pi
          join public.game_sessions ps on ps.id = pi.session_id
            and ps.couple_id = s.couple_id and ps.completed_at is not null
          left join public.game_session_answers pma on pma.item_id = pi.id and pma.actor_role = caller_role
          left join public.game_session_answers ppa on ppa.item_id = pi.id and ppa.actor_role <> caller_role
          where pi.id::text = i.context->>'previous_item_id') end
      ) order by i.position) from public.game_session_items i
      left join public.game_session_answers a on a.item_id = i.id and a.actor_role = caller_role
      left join public.game_session_answers pa on pa.item_id = i.id and pa.actor_role <> caller_role
      where i.session_id = s.id
    ), '[]'::jsonb)
  )
  from public.game_sessions s
  join public.game_session_sides mine on mine.session_id = s.id and mine.actor_role = caller_role
  join public.game_session_sides partner on partner.session_id = s.id and partner.actor_role <> caller_role
  where s.id = target_session_id and s.couple_id = current_couple;
$function$;

-- private.m11a_valid_options(target_kind text, target_question text, raw_options jsonb)
CREATE OR REPLACE FUNCTION private.m11a_valid_options(target_kind text, target_question text, raw_options jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare item jsonb; label text; cleaned jsonb := '[]'::jsonb;
begin
  if target_question is null or char_length(btrim(target_question)) not between 1 and 300
     or target_kind not in ('open', 'choice') then
    raise exception using errcode = '22023', message = 'invalid question';
  end if;
  if raw_options is null or jsonb_typeof(raw_options) <> 'array' then
    raise exception using errcode = '22023', message = 'invalid options';
  end if;
  if target_kind = 'open' then
    if jsonb_array_length(raw_options) <> 0 then
      raise exception using errcode = '22023', message = 'invalid options';
    end if;
    return cleaned;
  end if;
  if jsonb_array_length(raw_options) not between 2 and 4 then
    raise exception using errcode = '22023', message = 'invalid options';
  end if;
  for item in select value from jsonb_array_elements(raw_options) loop
    if jsonb_typeof(item) <> 'string' then
      raise exception using errcode = '22023', message = 'invalid options';
    end if;
    label := btrim(item #>> '{}');
    if char_length(label) not between 1 and 120 or cleaned ? label then
      raise exception using errcode = '22023', message = 'invalid options';
    end if;
    cleaned := cleaned || jsonb_build_array(label);
  end loop;
  return cleaned;
end;
$function$;

-- private.materialize_daily_question(target_date date)
CREATE OR REPLACE FUNCTION private.materialize_daily_question(target_date date)
 RETURNS daily_questions
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  existing public.daily_questions%rowtype;
  chosen public.daily_question_templates%rowtype;
  slot smallint;
begin
  if target_date is null then
    raise exception using errcode = '22004', message = 'daily_question_date_required';
  end if;

  select * into existing from public.daily_questions as q where q.question_date = target_date;
  if found then
    return existing;
  end if;

  -- One global key: selection reads the history, so materializations are
  -- serialized with each other (they are rare: at most one per day).
  perform pg_advisory_xact_lock(hashtextextended('us:daily_question:materialize', 0));

  select * into existing from public.daily_questions as q where q.question_date = target_date;
  if found then
    return existing;
  end if;

  slot := extract(isodow from target_date)::smallint;

  select t.* into chosen
    from public.daily_question_templates as t
    left join lateral (
      select max(q.question_date) as last_used
        from public.daily_questions as q
       where q.template_id = t.id
          or lower(btrim(q.question)) = lower(btrim(t.question))
    ) as usage on true
   where t.active
     and t.weekday_slot = slot
   order by usage.last_used asc nulls first, t.sequence asc, t.id asc
   limit 1;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'daily_question_template_bank_empty',
      detail = format('no active daily_question_templates row for ISO weekday %s (%s)', slot, target_date);
  end if;

  insert into public.daily_questions (question_date, question, template_id)
  values (target_date, chosen.question, chosen.id)
  on conflict (question_date) do nothing;

  select * into existing from public.daily_questions as q where q.question_date = target_date;
  if not found then
    raise exception using errcode = 'P0001', message = 'daily_question_materialization_failed';
  end if;
  return existing;
end;
$function$;
comment on function private.materialize_daily_question(target_date date) is 'M9E: returns the daily_questions row for target_date, creating exactly one from the template bank when missing. Never reads or writes answers.';

-- private.progression_award(target_couple uuid, target_actor uuid, target_source_kind text, target_source_key text, target_xp integer, target_action_at timestamp with time zone, target_counts_rhythm boolean, add_to_bond boolean)
CREATE OR REPLACE FUNCTION private.progression_award(target_couple uuid, target_actor uuid, target_source_kind text, target_source_key text, target_xp integer, target_action_at timestamp with time zone DEFAULT now(), target_counts_rhythm boolean DEFAULT true, add_to_bond boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  inserted_id uuid;
  current_xp integer;
  action_day date := (coalesce(target_action_at, now()) at time zone 'Europe/Rome')::date;
begin
  if target_couple is null or not exists (select 1 from public.couples c where c.id = target_couple) then
    raise exception using errcode = '22023', message = 'progression_couple_required';
  end if;
  if target_source_kind not in ('quest','event','milestone','daily','game','think','moment') then
    raise exception using errcode = '22023', message = 'progression_source_invalid';
  end if;
  if target_source_key is null or btrim(target_source_key) = '' or char_length(target_source_key) > 180 then
    raise exception using errcode = '22023', message = 'progression_source_key_invalid';
  end if;
  if coalesce(target_xp, 0) < 0 then
    raise exception using errcode = '22023', message = 'progression_xp_invalid';
  end if;
  if target_actor is not null and not exists (
    select 1 from public.profiles p where p.id = target_actor and p.couple_id = target_couple
  ) then
    raise exception using errcode = '42501', message = 'progression_actor_outside_couple';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('us:progression:' || target_couple::text, 0));

  insert into public.progression_events(
    couple_id, actor_id, source_kind, source_key, xp_awarded, counts_rhythm, action_day, created_at
  )
  values (
    target_couple, target_actor, target_source_kind, btrim(target_source_key),
    greatest(0, coalesce(target_xp, 0)), coalesce(target_counts_rhythm, true),
    action_day, coalesce(target_action_at, now())
  )
  on conflict (couple_id, source_kind, source_key) do nothing
  returning id into inserted_id;

  if inserted_id is not null and add_to_bond and coalesce(target_xp, 0) > 0 then
    update public.couples
       set bond_xp = coalesce(bond_xp, 0) + target_xp
     where id = target_couple
    returning bond_xp into current_xp;
  else
    select coalesce(c.bond_xp, 0) into current_xp from public.couples c where c.id = target_couple;
  end if;

  perform private.progression_sync_unlocks(target_couple, current_xp);

  return jsonb_build_object(
    'recorded', inserted_id is not null,
    'xp_added', case when inserted_id is not null and add_to_bond then greatest(0, coalesce(target_xp, 0)) else 0 end,
    'total_xp', coalesce(current_xp, 0),
    'level', private.progression_level(coalesce(current_xp, 0)),
    'action_day', action_day
  );
end;
$function$;

-- private.progression_couples_xp_trigger()
CREATE OR REPLACE FUNCTION private.progression_couples_xp_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.bond_xp is distinct from old.bond_xp then
    perform private.progression_sync_unlocks(new.id, coalesce(new.bond_xp, 0));
  end if;
  return new;
end;
$function$;

-- private.progression_daily_trigger()
CREATE OR REPLACE FUNCTION private.progression_daily_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  answered integer;
begin
  select count(distinct a.user_id)::integer into answered
    from public.daily_answers a
   where a.couple_id = new.couple_id and a.question_id = new.question_id;
  if answered >= 2 then
    perform private.progression_award(
      new.couple_id, new.user_id, 'daily', new.question_id::text, 10,
      coalesce(new.updated_at, new.created_at, now()), true, true
    );
  end if;
  return new;
end;
$function$;

