-- private.progression_level_info(total_xp integer)
CREATE OR REPLACE FUNCTION private.progression_level_info(total_xp integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  total integer := greatest(0, coalesce(total_xp, 0));
  level_no integer := 1;
  floor_xp integer := 0;
  needed integer := 200;
  current_xp integer;
begin
  while total >= floor_xp + needed loop
    floor_xp := floor_xp + needed;
    level_no := level_no + 1;
    needed := 200 + (level_no - 1) * 150;
    exit when level_no > 999;
  end loop;
  current_xp := total - floor_xp;
  return jsonb_build_object(
    'total_xp', total,
    'level', level_no,
    'current_xp', current_xp,
    'needed_xp', needed,
    'remaining_xp', greatest(0, needed - current_xp),
    'progress', case when needed > 0 then (current_xp::numeric / needed::numeric) else 0 end
  );
end;
$function$;

-- private.progression_level(total_xp integer)
CREATE OR REPLACE FUNCTION private.progression_level(total_xp integer)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  total integer := greatest(0, coalesce(total_xp, 0));
  level_no integer := 1;
  floor_xp integer := 0;
  needed integer := 200;
begin
  while total >= floor_xp + needed loop
    floor_xp := floor_xp + needed;
    level_no := level_no + 1;
    needed := 200 + (level_no - 1) * 150;
    exit when level_no > 999;
  end loop;
  return level_no;
end;
$function$;

