$function$;

-- public.confirm_bucket_item_lived(p_item_id uuid)
CREATE OR REPLACE FUNCTION public.confirm_bucket_item_lived(p_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_item public.bucket_items%rowtype;
  v_seen_proposer uuid;
  v_seen_couple uuid;
  v_ids uuid[];
  v_lock record;
  v_caller_couple uuid;
  v_proposer_couple uuid;
  v_proposer_is_member boolean := false;
begin
  if v_uid is null then
    raise exception using errcode = '42501', message = 'bucket_items_lived_requires_authenticated_member';
  end if;

  -- Strategia di lock (stesso ordine del flusso claim_us_role, che blocca il
  -- profilo PRIMA delle righe bucket_items: profili -> riga, mai il contrario,
  -- quindi nessun deadlock con il re-pair):
  --   1. lettura SENZA lock della riga, solo per sapere coppia e proponente;
  --   2. lock FOR SHARE dei profili coinvolti (chi chiama + proponente), in
  --      ordine deterministico per id: un re-pair/rimozione (che li blocca
  --      FOR UPDATE o li cancella) aspetta la fine di questa transazione, e
  --      chi è già stato rimosso non si vede più (la lettura sotto lock è
  --      quella corrente, non quella di prima dell'attesa);
  --   3. lock FOR UPDATE della riga e RIVERIFICA dopo l'attesa: coppia e
  --      proponente devono essere ancora quelli su cui abbiamo bloccato i
  --      profili, altrimenti 40001 (retry sicuro: la RPC è idempotente).
  select b.couple_id, b.lived_proposed_by into v_seen_couple, v_seen_proposer
  from public.bucket_items b where b.id = p_item_id;
  -- Stesso errore per "non esiste" e "è di un'altra coppia": la RPC non
  -- rivela l'esistenza di righe fuori dalla coppia di chi chiama.
  if not found then
    raise exception using errcode = 'P0002', message = 'bucket_items_not_found';
  end if;

  v_ids := array[v_uid];
  if v_seen_proposer is not null and v_seen_proposer <> v_uid then
    v_ids := v_ids || v_seen_proposer;
  end if;

  for v_lock in
    select p.id, p.couple_id from public.profiles p
    where p.id = any(v_ids)
    order by p.id
    for share
  loop
    if v_lock.id = v_uid then v_caller_couple := v_lock.couple_id; end if;
    if v_lock.id = v_seen_proposer then v_proposer_couple := v_lock.couple_id; end if;
  end loop;

  if v_caller_couple is null then
    raise exception using errcode = '42501', message = 'bucket_items_lived_requires_authenticated_member';
  end if;
  if v_caller_couple <> v_seen_couple then
    raise exception using errcode = 'P0002', message = 'bucket_items_not_found';
  end if;

  select b.* into v_item from public.bucket_items b where b.id = p_item_id for update;
  if not found or v_item.couple_id <> v_caller_couple then
    raise exception using errcode = 'P0002', message = 'bucket_items_not_found';
  end if;
  if v_item.lived_proposed_by is distinct from v_seen_proposer then
    raise exception using errcode = '40001', message = 'bucket_items_lived_proposal_changed_retry';
  end if;

  if v_item.status not in ('idea', 'scheduled', 'lived') then
    raise exception using errcode = '22023', message = format('bucket_items_lived_not_allowed_from: %s', v_item.status);
  end if;

  if v_item.status <> 'lived' then
    -- Il proponente vale solo se è ANCORA membro della stessa coppia (letto
    -- sotto lock: non può cambiare fino al commit).
    v_proposer_is_member := v_item.lived_proposed_by is not null
      and v_item.lived_proposed_by <> v_uid
      and v_proposer_couple is not distinct from v_item.couple_id;

    perform set_config('us.bucket_items_lived_confirm', 'on', true);
    if v_item.lived_proposed_by is null
       or (v_item.lived_proposed_by <> v_uid and not v_proposer_is_member) then
      update public.bucket_items
        set lived_proposed_by = v_uid, lived_proposed_at = now()
        where id = p_item_id;
    elsif v_item.lived_proposed_by <> v_uid then
      update public.bucket_items set status = 'lived' where id = p_item_id;
    end if;
    perform set_config('us.bucket_items_lived_confirm', 'off', true);
  end if;

  select b.* into v_item from public.bucket_items b where b.id = p_item_id;
  return jsonb_build_object(
    'id', v_item.id,
    'status', v_item.status,
    'calendar_entry_id', v_item.calendar_entry_id,
    'completed', v_item.completed,
    'completed_at', v_item.completed_at,
    'lived_proposed_by', v_item.lived_proposed_by,
    'lived_proposed_at', v_item.lived_proposed_at
  );
end;
$function$;

-- public.conserve_left_for_you(target_item_id uuid)
CREATE OR REPLACE FUNCTION public.conserve_left_for_you(target_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_item public.left_for_you%rowtype;
  existing_row public.conserva_contributions%rowtype;
  created_row public.conserva_contributions%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;

  select entry.* into target_item
  from public.left_for_you as entry
  where entry.id = target_item_id
    and entry.couple_id = private.current_couple_id()
    and entry.recipient_id = auth.uid()
  for update;

  if target_item.id is null then
    raise exception using errcode = '42501', message = 'conserva_recipient_required';
  end if;

  insert into public.conserva_contributions as c
    (couple_id, source_item_id, source_sender_id, conserved_by)
  values
    (target_item.couple_id, target_item.id, target_item.sender_id, auth.uid())
  on conflict (source_item_id) do nothing
  returning c.* into created_row;

  if created_row.id is not null then
    return jsonb_build_object(
      'id', created_row.id,
      'status', 'created',
      'couple_id', created_row.couple_id,
      'source_item_id', created_row.source_item_id,
      'source_sender_id', created_row.source_sender_id,
      'conserved_by', created_row.conserved_by,
      'created_at', created_row.created_at
    );
  end if;

  select e.* into existing_row
  from public.conserva_contributions as e
  where e.source_item_id = target_item.id;

  return jsonb_build_object(
    'id', existing_row.id,
    'status', 'existing',
    'couple_id', existing_row.couple_id,
    'source_item_id', existing_row.source_item_id,
    'source_sender_id', existing_row.source_sender_id,
    'conserved_by', existing_row.conserved_by,
    'created_at', existing_row.created_at
  );
end;
$function$;

-- public.create_couple_question(request_id uuid, question_text text, answer_kind text, options jsonb)
CREATE OR REPLACE FUNCTION public.create_couple_question(request_id uuid, question_text text, answer_kind text, options jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; normalized jsonb; q public.couple_questions%rowtype;
begin
  select * into actor from private.m11a_actor_locked();
  if request_id is null then raise exception using errcode = '22023', message = 'request id required'; end if;
  normalized := private.m11a_valid_options(answer_kind, question_text, options);
  insert into public.couple_questions(couple_id, author_role, create_request_id, question_text, answer_kind, options)
  values (actor.caller_couple, actor.caller_role, request_id, btrim(question_text), answer_kind, normalized)
  on conflict (couple_id, author_role, create_request_id) do nothing returning * into q;
  if q.id is null then
    select * into q from public.couple_questions
    where couple_id = actor.caller_couple and author_role = actor.caller_role and create_request_id = request_id;
    if q.question_text <> btrim(question_text) or q.answer_kind <> answer_kind or q.options <> normalized then
      raise exception using errcode = '22023', message = 'request already used';
    end if;
  end if;
  return private.m11a_question_json(q);
end;
$function$;

-- public.create_weekly_question(request_id uuid, question_text text, answer_kind text, options jsonb, families text[])
CREATE OR REPLACE FUNCTION public.create_weekly_question(request_id uuid, question_text text, answer_kind text, options jsonb, families text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; normalized jsonb; cleaned_families text[]; week date; existing public.couple_questions%rowtype;
  at_time timestamptz := private.game_v2_clock();
begin
  select * into actor from private.m11a_actor_locked();
  if request_id is null then raise exception using errcode = '22023', message = 'request id required'; end if;
  normalized := private.m11a_valid_options(answer_kind, question_text, options);
  cleaned_families := private.game_v2_valid_families(families, answer_kind);
  -- Serialize every weekly write of the couple (double taps, both partners,
  -- a retry racing its original); the partial unique index stays the final
  -- authority.
  perform pg_advisory_xact_lock(hashtextextended('game_v2_weekly:' || actor.caller_couple::text, 0));

  select * into existing from public.couple_questions q
    where q.couple_id = actor.caller_couple and q.author_role = actor.caller_role
      and q.create_request_id = create_weekly_question.request_id;
  if existing.id is not null then
    if existing.origin <> 'weekly' or existing.question_text <> btrim(create_weekly_question.question_text)
      or existing.answer_kind <> create_weekly_question.answer_kind or existing.options <> normalized
      or existing.families <> cleaned_families then
      raise exception using errcode = '22023', message = 'request already used';
    end if;
    return private.game_v2_weekly_state(actor.caller_couple, actor.caller_role, at_time)
      || jsonb_build_object('question_id', existing.id, 'replayed', true);
  end if;

  week := private.game_v2_week_start(at_time);
  if private.game_v2_weekly_role(week) <> actor.caller_role then
    raise exception using errcode = '42501', message = 'not your turn';
  end if;
  if exists (select 1 from public.couple_questions q
      where q.couple_id = actor.caller_couple and q.origin = 'weekly' and q.week_start = week) then
    raise exception using errcode = '23505', message = 'weekly question already created';
  end if;
  insert into public.couple_questions(couple_id, author_role, create_request_id, question_text,
    answer_kind, options, origin, week_start, families)
  values (actor.caller_couple, actor.caller_role, create_weekly_question.request_id,
    btrim(create_weekly_question.question_text), create_weekly_question.answer_kind, normalized,
    'weekly', week, cleaned_families)
  returning * into existing;
  return private.game_v2_weekly_state(actor.caller_couple, actor.caller_role, at_time)
    || jsonb_build_object('question_id', existing.id, 'replayed', false);
end;
$function$;

-- public.delete_daily_question_outcome(target_question_id uuid, expected_revision integer)
CREATE OR REPLACE FUNCTION public.delete_daily_question_outcome(target_question_id uuid, expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_couple uuid;
  actor_role text;
  existing public.daily_question_outcomes%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;

  select profile.couple_id, profile.role
    into current_couple, actor_role
    from public.profiles as profile
   where profile.id = auth.uid()
     and profile.couple_id is not null;

  if current_couple is null or actor_role not in ('francesco', 'beatrice') then
    raise exception using errcode = '42501', message = 'couple membership required';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(current_couple::text || ':' || target_question_id::text || ':' || actor_role, 0)
  );

  select *
    into existing
    from public.daily_question_outcomes as outcome
   where outcome.couple_id = current_couple
     and outcome.question_id = target_question_id
     and outcome.author_role = actor_role
   for update;

  if existing.id is null then
    return jsonb_build_object('status', 'already_absent');
  end if;

  if expected_revision is null or expected_revision <> existing.revision then
    return jsonb_build_object('status', 'stale', 'id', existing.id, 'revision', existing.revision);
  end if;

  delete from public.daily_question_outcomes where id = existing.id;
  return jsonb_build_object('status', 'deleted', 'id', existing.id, 'revision', existing.revision);
end;
$function$;

-- public.delete_think_reaction(target_message_id uuid)
CREATE OR REPLACE FUNCTION public.delete_think_reaction(target_message_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_couple uuid;
  message public.shared_messages%rowtype;
  deleted_id uuid;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;

  current_couple := private.current_couple_id();
  select * into message
    from public.shared_messages
   where id = target_message_id
     and kind = 'think'
     and couple_id = current_couple
     and recipient_id = auth.uid()
   for update;
  if message.id is null then
    raise exception using errcode = '42501', message = 'think recipient required';
  end if;

  delete from public.think_reactions
   where message_id = target_message_id
  returning id into deleted_id;

  return jsonb_build_object('status', case when deleted_id is null then 'already_absent' else 'deleted' end, 'message_id', target_message_id);
end;
$function$;

-- public.dismiss_daily_reveal_notice(target_question_id uuid)
CREATE OR REPLACE FUNCTION public.dismiss_daily_reveal_notice(target_question_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ctx record;
begin
  select * into ctx from private.daily_reveal_context(target_question_id);
  if not ctx.ready then
    raise exception using errcode = '42501', message = 'daily question reveal is not ready';
  end if;

  insert into public.daily_question_reveal_states as state (couple_id, question_id, actor_role, notice_dismissed_at)
  values (ctx.caller_couple, target_question_id, ctx.caller_role, now())
  on conflict (couple_id, question_id, actor_role) do update
    set notice_dismissed_at = coalesce(state.notice_dismissed_at, excluded.notice_dismissed_at),
        updated_at = now();

  return private.daily_reveal_meta(target_question_id, ctx.caller_couple, ctx.caller_role, true);
end;
$function$;
comment on function public.dismiss_daily_reveal_notice(target_question_id uuid) is 'M10.2: caller hides the Oggi "Risposte pronte" notice. Idempotent; does NOT mark the reveal as seen.';

