-- public.equip_progression_reward(target_reward_id text)
CREATE OR REPLACE FUNCTION public.equip_progression_reward(target_reward_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid := auth.uid();
  cid uuid;
  reward public.progression_reward_catalog%rowtype;
  prefs public.couple_progression_preferences%rowtype;
  current_id text;
  next_id text;
begin
  if uid is null then raise exception using errcode = '42501', message = 'authentication required'; end if;
  select p.couple_id into cid from public.profiles p where p.id = uid;
  if cid is null then raise exception using errcode = '42501', message = 'couple membership required'; end if;

  select r.* into reward
    from public.progression_reward_catalog r
   where r.id = target_reward_id and r.active = true;
  if reward.id is null then raise exception using errcode = '22023', message = 'reward unavailable'; end if;

  if not exists (
    select 1
      from public.couple_reward_unlocks u
     where u.couple_id = cid and u.reward_id = reward.id
  ) then
    raise exception using errcode = '42501', message = 'reward not unlocked';
  end if;

  insert into public.couple_progression_preferences(couple_id, updated_by, updated_at)
  values (cid, uid, now())
  on conflict (couple_id) do nothing;

  select pref.* into prefs
    from public.couple_progression_preferences pref
   where pref.couple_id = cid
   for update;

  current_id := case reward.category
    when 'frame' then prefs.frame_reward_id
    when 'theme' then prefs.theme_reward_id
    when 'accent' then prefs.accent_reward_id
    when 'effect' then prefs.effect_reward_id
    when 'badge' then prefs.badge_reward_id
    when 'sticker' then prefs.sticker_reward_id
    when 'ring' then prefs.ring_reward_id
  end;
  next_id := case when current_id = reward.id then null else reward.id end;

  update public.couple_progression_preferences pref set
    frame_reward_id   = case when reward.category = 'frame'   then next_id else pref.frame_reward_id end,
    theme_reward_id   = case when reward.category = 'theme'   then next_id else pref.theme_reward_id end,
    accent_reward_id  = case when reward.category = 'accent'  then next_id else pref.accent_reward_id end,
    effect_reward_id  = case when reward.category = 'effect'  then next_id else pref.effect_reward_id end,
    badge_reward_id   = case when reward.category = 'badge'   then next_id else pref.badge_reward_id end,
    sticker_reward_id = case when reward.category = 'sticker' then next_id else pref.sticker_reward_id end,
    ring_reward_id    = case when reward.category = 'ring'    then next_id else pref.ring_reward_id end,
    updated_by = uid,
    updated_at = now()
  where pref.couple_id = cid;

  return public.get_progression_v1();
end;
$function$;

-- public.finalize_left_for_you_cleanup(target_item_id uuid)
CREATE OR REPLACE FUNCTION public.finalize_left_for_you_cleanup(target_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  queued_item private.left_for_you_cleanup_queue%rowtype;
  source_item public.left_for_you%rowtype;
  deleted_id uuid;
begin
  select * into queued_item
  from private.left_for_you_cleanup_queue
  where item_id = target_item_id
    and completed_at is null
  for update;

  if queued_item.item_id is null then
    return jsonb_build_object('status', 'absent', 'item_id', target_item_id);
  end if;

  if queued_item.source_deleted_at is not null then
    update private.left_for_you_cleanup_queue
    set claimed_at = null
    where item_id = queued_item.item_id;
    return jsonb_build_object(
      'status', 'source_deleted',
      'item_id', queued_item.item_id,
      'couple_id', queued_item.couple_id,
      'sender_id', queued_item.sender_id,
      'kind', queued_item.kind,
      'media_path', queued_item.media_path
    );
  end if;

  select * into source_item
  from public.left_for_you
  where id = queued_item.item_id
  for update;

  if source_item.id is null then
    update private.left_for_you_cleanup_queue
    set source_deleted_at = now(), claimed_at = null
    where item_id = queued_item.item_id;
    return jsonb_build_object(
      'status', 'source_deleted',
      'item_id', queued_item.item_id,
      'couple_id', queued_item.couple_id,
      'sender_id', queued_item.sender_id,
      'kind', queued_item.kind,
      'media_path', queued_item.media_path
    );
  end if;

  if exists (
    select 1
    from public.conserva_contributions as contribution
    where contribution.source_item_id = source_item.id
  ) then
    delete from private.left_for_you_cleanup_queue
    where item_id = queued_item.item_id;
    return jsonb_build_object('status', 'conserved', 'item_id', queued_item.item_id);
  end if;

  if source_item.cleanup_eligible_at is null
     or source_item.seen_at is null
     or source_item.seen_at >= now() - interval '30 days' then
    delete from private.left_for_you_cleanup_queue
    where item_id = queued_item.item_id;
    return jsonb_build_object('status', 'not_eligible', 'item_id', queued_item.item_id);
  end if;

  delete from public.left_for_you
  where id = source_item.id
    and not exists (
      select 1
      from public.conserva_contributions as contribution
      where contribution.source_item_id = source_item.id
    )
  returning id into deleted_id;

  if deleted_id is null then
    return jsonb_build_object('status', 'conserved_or_raced', 'item_id', queued_item.item_id);
  end if;

  update private.left_for_you_cleanup_queue
  set source_deleted_at = now(), claimed_at = null
  where item_id = queued_item.item_id;

  return jsonb_build_object(
    'status', 'source_deleted',
    'item_id', deleted_id,
    'couple_id', queued_item.couple_id,
    'sender_id', queued_item.sender_id,
    'kind', queued_item.kind,
    'media_path', queued_item.media_path
  );
end;
$function$;

-- public.game_v2_pending_pushes()
CREATE OR REPLACE FUNCTION public.game_v2_pending_pushes()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with clock as (select private.game_v2_clock() t),
  week as (select private.game_v2_week_start(t) w from clock),
  events as (
    select private.game_v2_push_event('game_weekly_turn', c.id, private.game_v2_weekly_role(week.w), null, week.w::text) e
    from public.couples c cross join week
    where (select count(distinct p.role) from public.profiles p
        where p.couple_id = c.id and p.role in ('francesco', 'beatrice')) = 2
      and not exists (select 1 from public.couple_questions q
        where q.couple_id = c.id and q.origin = 'weekly' and q.week_start = week.w)
    union all
    select private.game_v2_push_event('game_weekly_created', q.couple_id, private.game_v2_partner_role(q.author_role),
      q.author_role, q.week_start::text)
    from public.couple_questions q cross join week cross join clock
    where q.origin = 'weekly' and q.week_start = week.w and q.archived_at is null
      and q.created_at <= clock.t - interval '2 minutes'
    union all
    select private.game_v2_push_event('game_waiting', s.couple_id, open_side.actor_role, done_side.actor_role, s.id::text)
    from public.game_sessions s cross join clock
    join public.game_session_sides done_side on done_side.session_id = s.id and done_side.completed_at is not null
    join public.game_session_sides open_side on open_side.session_id = s.id and open_side.completed_at is null
    where s.engine_version = 2 and s.completed_at is null
      and done_side.completed_at between clock.t - interval '48 hours' and clock.t - interval '2 minutes'
    union all
    select private.game_v2_push_event('game_reveal', s.couple_id, first_side.actor_role, null, s.id::text)
    from public.game_sessions s cross join clock
    join public.game_session_sides first_side on first_side.session_id = s.id
    join public.game_session_sides last_side on last_side.session_id = s.id and last_side.actor_role <> first_side.actor_role
    where s.engine_version = 2 and s.completed_at between clock.t - interval '48 hours' and clock.t - interval '2 minutes'
      and (first_side.completed_at, first_side.actor_role) < (last_side.completed_at, last_side.actor_role)
      and first_side.reveal_seen_at is null
  )
  select coalesce(jsonb_agg(events.e order by events.e->>'dedupe_key'), '[]'::jsonb) from events;
$function$;

-- public.game_v2_push_for_session(target_session_id uuid, actor_id uuid)
CREATE OR REPLACE FUNCTION public.game_v2_push_for_session(target_session_id uuid, actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a_couple uuid; a_role text; session_couple uuid; session_done timestamptz;
  my_done timestamptz; p_role text; partner_done timestamptz; partner_seen timestamptz;
begin
  select p.couple_id, p.role into a_couple, a_role from public.profiles p where p.id = actor_id;
  if a_couple is null or a_role not in ('francesco', 'beatrice') then return null; end if;
  select s.couple_id, s.completed_at into session_couple, session_done from public.game_sessions s
    where s.id = target_session_id and s.couple_id = a_couple and s.engine_version = 2;
  if session_couple is null then return null; end if;
  select d.completed_at into my_done from public.game_session_sides d
    where d.session_id = target_session_id and d.actor_role = a_role;
  select d.actor_role, d.completed_at, d.reveal_seen_at into p_role, partner_done, partner_seen
    from public.game_session_sides d where d.session_id = target_session_id and d.actor_role <> a_role;
  if my_done is null or p_role is null then return null; end if;
  if session_done is null then
    return private.game_v2_push_event('game_waiting', a_couple, p_role, a_role, target_session_id::text);
  end if;
  -- Whoever finished first (ties broken by role) is the one still waiting.
  if partner_done is not null and (partner_done, p_role) < (my_done, a_role) and partner_seen is null then
    return private.game_v2_push_event('game_reveal', a_couple, p_role, null, target_session_id::text);
  end if;
  return null;
end;
$function$;

-- public.game_v2_push_for_weekly(target_question_id uuid, actor_id uuid)
CREATE OR REPLACE FUNCTION public.game_v2_push_for_weekly(target_question_id uuid, actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a_couple uuid; a_role text; week date := private.game_v2_week_start(private.game_v2_clock());
begin
  select p.couple_id, p.role into a_couple, a_role from public.profiles p where p.id = actor_id;
  if a_couple is null or a_role not in ('francesco', 'beatrice') then return null; end if;
  if not exists (select 1 from public.couple_questions q
      where q.id = target_question_id and q.couple_id = a_couple and q.origin = 'weekly'
        and q.author_role = a_role and q.week_start = week and q.archived_at is null) then
    return null;
  end if;
  return private.game_v2_push_event('game_weekly_created', a_couple, private.game_v2_partner_role(a_role),
    a_role, week::text);
end;
$function$;

