 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); cid uuid; ws date := date_trunc('week', current_timestamp at time zone 'Europe/Rome')::date; week_index integer := ((ws - date '2026-08-17') / 7)::integer; result jsonb;
begin
