-- public.save_daily_question_outcome(target_question_id uuid, target_body text, operation_id uuid, expected_revision integer)
CREATE OR REPLACE FUNCTION public.save_daily_question_outcome(target_question_id uuid, target_body text, operation_id uuid, expected_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_couple uuid;
  actor_role text;
  existing public.daily_question_outcomes%rowtype;
  normalized_body text := btrim(target_body);
  next_revision integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;

  if operation_id is null then
    raise exception using errcode = '22004', message = 'operation_id required';
  end if;

  if normalized_body is null or char_length(normalized_body) not between 1 and 1000 then
    raise exception using errcode = '22023', message = 'outcome body must contain 1..1000 characters';
  end if;

  select profile.couple_id, profile.role
    into current_couple, actor_role
    from public.profiles as profile
   where profile.id = auth.uid()
     and profile.couple_id is not null;

  if current_couple is null or actor_role not in ('francesco', 'beatrice') then
    raise exception using errcode = '42501', message = 'couple membership required';
  end if;

  if not private.daily_question_reveal_ready(target_question_id) then
    raise exception using errcode = '42501', message = 'daily question reveal is not ready';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(current_couple::text || ':' || target_question_id::text || ':' || actor_role, 0)
  );

  select *
    into existing
    from public.daily_question_outcomes as outcome
   where outcome.couple_id = current_couple
     and outcome.question_id = target_question_id
     and outcome.author_role = actor_role
   for update;

  if existing.id is not null then
    if existing.last_operation_id = operation_id then
      return jsonb_build_object('status', 'duplicate', 'id', existing.id, 'revision', existing.revision, 'body', existing.body);
    end if;
    if expected_revision is null or expected_revision <> existing.revision then
      return jsonb_build_object('status', 'stale', 'id', existing.id, 'revision', existing.revision);
    end if;

    next_revision := existing.revision + 1;
    update public.daily_question_outcomes
       set body = normalized_body,
           revision = next_revision,
           last_operation_id = operation_id,
           updated_at = now()
     where id = existing.id
     returning * into existing;

    return jsonb_build_object('status', 'saved', 'id', existing.id, 'revision', existing.revision, 'body', existing.body);
  end if;

  if expected_revision is not null then
    return jsonb_build_object('status', 'stale', 'revision', 0);
  end if;

  insert into public.daily_question_outcomes (couple_id, question_id, author_role, body, last_operation_id)
  values (current_couple, target_question_id, actor_role, normalized_body, operation_id)
  returning * into existing;

  return jsonb_build_object('status', 'saved', 'id', existing.id, 'revision', existing.revision, 'body', existing.body);
end;
$function$;

-- public.save_game_session_answer(target_session_id uuid, target_item_id uuid, target_answer_text text, target_answer_index smallint)
CREATE OR REPLACE FUNCTION public.save_game_session_answer(target_session_id uuid, target_item_id uuid, target_answer_text text, target_answer_index smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; s public.game_sessions%rowtype; i public.game_session_items%rowtype;
  locked_at timestamptz; existing public.game_session_answers%rowtype; normalized_text text;
begin
  select * into actor from private.m11a_actor_locked();
  select * into s from public.game_sessions
    where id = target_session_id and couple_id = actor.caller_couple for update;
  if s.id is null then raise exception using errcode = '42501', message = 'session unavailable'; end if;
  select * into i from public.game_session_items
    where id = target_item_id and session_id = s.id;
  if i.id is null then raise exception using errcode = '42501', message = 'item unavailable'; end if;
  if i.answer_kind = 'open' then
    normalized_text := btrim(target_answer_text);
    if target_answer_index is not null or normalized_text is null
      or char_length(normalized_text) not between 1 and 1000 then
      raise exception using errcode = '22023', message = 'invalid answer';
    end if;
  elsif target_answer_text is not null or target_answer_index is null
    or target_answer_index < 0 or target_answer_index >= jsonb_array_length(i.options) then
    raise exception using errcode = '22023', message = 'invalid answer';
  end if;
  select completed_at into locked_at from public.game_session_sides
    where session_id = s.id and actor_role = actor.caller_role;
  if locked_at is not null then
    select * into existing from public.game_session_answers
      where item_id = i.id and actor_role = actor.caller_role;
    if existing.item_id is not null and existing.answer_text is not distinct from normalized_text
      and existing.answer_index is not distinct from target_answer_index then
      return private.m11a_session_state(s.id, actor.caller_couple, actor.caller_role);
    end if;
    raise exception using errcode = '42501', message = 'answer locked';
  end if;
  insert into public.game_session_answers(item_id, actor_role, answer_text, answer_index)
    values(i.id, actor.caller_role, normalized_text, target_answer_index)
    on conflict (item_id, actor_role) do update
      set answer_text = excluded.answer_text, answer_index = excluded.answer_index, updated_at = now();
  return private.m11a_session_state(s.id, actor.caller_couple, actor.caller_role);
end;
$function$;

-- public.save_quiz_answer(target_question_id uuid, target_answer_index smallint)
CREATE OR REPLACE FUNCTION public.save_quiz_answer(target_question_id uuid, target_answer_index smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
  cid uuid;
  sid uuid;
  option_count integer;
  ws date := date_trunc('week', current_timestamp at time zone 'Europe/Rome')::date;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select couple_id into cid from public.profiles where id=uid;
  if cid is null then raise exception 'Profile not linked'; end if;
  select set_id, jsonb_array_length(options) into sid, option_count from public.quiz_questions where id=target_question_id;
  if sid is null then raise exception 'Quiz question not found'; end if;
  if target_answer_index < 0 or target_answer_index >= option_count then raise exception 'Invalid answer index'; end if;

  insert into public.quiz_responses(set_id,question_id,user_id,couple_id,answer_index,week_start,updated_at)
  values (sid,target_question_id,uid,cid,target_answer_index,ws,now())
  on conflict (question_id,user_id,week_start)
  do update set answer_index=excluded.answer_index,set_id=excluded.set_id,couple_id=excluded.couple_id,updated_at=now();

  return jsonb_build_object('saved',true,'set_id',sid,'question_id',target_question_id,'week_start',ws);
end;
$function$;
comment on function public.save_quiz_answer(target_question_id uuid, target_answer_index smallint) is 'RETIRED (US 2.0 F1B): Gioca v1, no client caller since M11B. EXECUTE revoked from public/anon/authenticated.';

-- public.send_think(operation_id uuid)
CREATE OR REPLACE FUNCTION public.send_think(operation_id uuid)
 RETURNS TABLE(message_id uuid, sender_id uuid, recipient_id uuid, couple_id uuid, duplicate boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := auth.uid();
  current_couple uuid;
  partner uuid;
  existing public.shared_messages%rowtype;
  created public.shared_messages%rowtype;
begin
  if actor is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;

  if operation_id is null then
    raise exception using errcode = '22004', message = 'operation_id required';
  end if;

  select message.* into existing
  from public.shared_messages as message
  where message.kind = 'think'
    and message.sender_id = actor
    and message.think_operation_id = operation_id
  for update;

  if existing.id is not null then
    return query select existing.id, existing.sender_id, existing.recipient_id,
      existing.couple_id, true;
    return;
  end if;

  current_couple := private.current_couple_id();

  select p.id into partner
  from public.profiles as p
  where p.couple_id = current_couple
    and p.id <> actor
  order by p.created_at, p.id
  limit 1;

  if partner is null then
    raise exception using errcode = 'P0001', message = 'think_partner_missing';
  end if;

  insert into public.shared_messages(
    couple_id, sender_id, recipient_id, kind, body, think_operation_id
  )
  values (
    current_couple, actor, partner, 'think', 'Ti penso', operation_id
  )
  on conflict do nothing
  returning * into created;

  if created.id is null then
    select message.* into existing
    from public.shared_messages as message
    where message.kind = 'think'
      and message.sender_id = actor
      and message.think_operation_id = operation_id;

    if existing.id is null then
      raise exception using errcode = 'P0001', message = 'think_send_conflict_unresolved';
    end if;

    return query select existing.id, existing.sender_id, existing.recipient_id,
      existing.couple_id, true;
    return;
  end if;

  return query select created.id, created.sender_id, created.recipient_id,
    created.couple_id, false;
end;
$function$;

-- public.set_daily_answer_reaction(target_question_id uuid, target_reaction text)
CREATE OR REPLACE FUNCTION public.set_daily_answer_reaction(target_question_id uuid, target_reaction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ctx record;
begin
  if target_reaction is not null and target_reaction not in ('heart', 'angry', 'cry') then
    raise exception using errcode = '22023', message = 'invalid daily reaction';
  end if;

  select * into ctx from private.daily_reveal_context(target_question_id);
  if not ctx.ready then
    raise exception using errcode = '42501', message = 'daily question reveal is not ready';
  end if;

  insert into public.daily_question_reveal_states as state (couple_id, question_id, actor_role, reaction)
  values (ctx.caller_couple, target_question_id, ctx.caller_role, target_reaction)
  on conflict (couple_id, question_id, actor_role) do update
    set reaction = excluded.reaction,
        updated_at = now();

  return private.daily_reveal_meta(target_question_id, ctx.caller_couple, ctx.caller_role, true);
end;
$function$;
comment on function public.set_daily_answer_reaction(target_question_id uuid, target_reaction text) is 'M10.2: caller reaction (heart|angry|cry, null clears) to the PARTNER answer. Requires both answered.';

-- public.set_notification_preference(target_key text, target_value boolean)
CREATE OR REPLACE FUNCTION public.set_notification_preference(target_key text, target_value boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
  prefs public.notification_preferences%rowtype;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  if target_key not in ('think', 'today', 'bond', 'relationship', 'left_for_you', 'games') then
    raise exception 'Invalid preference';
  end if;
  insert into public.notification_preferences(user_id) values(uid)
  on conflict(user_id) do nothing;
  if target_key = 'think' then
    update public.notification_preferences set think = target_value, updated_at = now() where user_id = uid;
  elsif target_key = 'today' then
    update public.notification_preferences set today = target_value, updated_at = now() where user_id = uid;
  elsif target_key = 'bond' then
    update public.notification_preferences set bond = target_value, updated_at = now() where user_id = uid;
  elsif target_key = 'relationship' then
    update public.notification_preferences set relationship = target_value, updated_at = now() where user_id = uid;
  elsif target_key = 'left_for_you' then
    update public.notification_preferences set left_for_you = target_value, updated_at = now() where user_id = uid;
  else
    update public.notification_preferences set games = target_value, updated_at = now() where user_id = uid;
  end if;
  select * into prefs from public.notification_preferences where user_id = uid;
  return jsonb_build_object(
    'think', prefs.think,
    'today', prefs.today,
    'bond', prefs.bond,
    'relationship', prefs.relationship,
    'left_for_you', prefs.left_for_you,
    'games', prefs.games
  );
end;
$function$;

-- public.set_think_reaction(target_message_id uuid, target_reaction text)
CREATE OR REPLACE FUNCTION public.set_think_reaction(target_message_id uuid, target_reaction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_couple uuid;
  message public.shared_messages%rowtype;
  existing public.think_reactions%rowtype;
  result public.think_reactions%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication required';
  end if;

  if target_reaction not in ('heart', 'hug', 'miss_you') then
    raise exception using errcode = '22023', message = 'invalid think reaction';
  end if;

  current_couple := private.current_couple_id();

  select msg.* into message
  from public.shared_messages as msg
  where msg.id = target_message_id
    and msg.kind = 'think'
    and msg.couple_id = current_couple
    and msg.recipient_id = auth.uid()
  for update;

  if message.id is null then
    raise exception using errcode = '42501', message = 'think recipient required';
  end if;

  select reaction.* into existing
  from public.think_reactions as reaction
  where reaction.message_id = target_message_id
  for update;

  if existing.id is not null then
    if existing.reaction = target_reaction then
      return jsonb_build_object(
        'status', 'duplicate',
        'id', existing.id,
        'message_id', existing.message_id,
        'reaction', existing.reaction,
        'updated_at', existing.updated_at
      );
    end if;

    raise exception using errcode = '23505', message = 'already_reacted';
  end if;

  insert into public.think_reactions (message_id, reaction)
  values (target_message_id, target_reaction)
  returning * into result;

  return jsonb_build_object(
    'status', 'saved',
    'id', result.id,
    'message_id', result.message_id,
    'reaction', result.reaction,
    'updated_at', result.updated_at
  );
end;
$function$;

-- public.start_custom_game_session(target_question_id uuid, request_id uuid)
CREATE OR REPLACE FUNCTION public.start_custom_game_session(target_question_id uuid, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; q public.couple_questions%rowtype; sid uuid; original_question uuid;
begin
  select * into actor from private.m11a_actor_locked();
  if request_id is null then raise exception using errcode = '22023', message = 'request id required'; end if;
  -- Check the receipt first: a retry must still work after the source is edited
  -- or archived. Unique (couple, role, request) resolves concurrent first calls.
  select s.id, i.source_question_id into sid, original_question
    from public.game_sessions s join public.game_session_items i on i.session_id = s.id and i.position = 1
    where s.couple_id = actor.caller_couple and s.started_by_role = actor.caller_role
      and s.create_request_id = request_id;
  if sid is not null then
    if original_question is distinct from target_question_id then
      raise exception using errcode = '22023', message = 'request already used';
    end if;
    return private.m11a_session_state(sid, actor.caller_couple, actor.caller_role);
  end if;
  select * into q from public.couple_questions
    where id = target_question_id and couple_id = actor.caller_couple and archived_at is null for share;
  if q.id is null then raise exception using errcode = '42501', message = 'question unavailable'; end if;
  insert into public.game_sessions(couple_id, game_family, content_source, started_by_role, create_request_id)
    values(actor.caller_couple, 'couple_custom', 'couple_custom', actor.caller_role, request_id)
    on conflict (couple_id, started_by_role, create_request_id) do nothing returning id into sid;
  if sid is null then
    select s.id, i.source_question_id into sid, original_question
      from public.game_sessions s join public.game_session_items i on i.session_id = s.id and i.position = 1
      where s.couple_id = actor.caller_couple and s.started_by_role = actor.caller_role
        and s.create_request_id = request_id;
    if sid is null or original_question is distinct from target_question_id then
      raise exception using errcode = '22023', message = 'request already used';
    end if;
  else
    insert into public.game_session_items(session_id, position, source_question_id, source_version,
      question_text, answer_kind, options)
      values(sid, 1, q.id, q.version, q.question_text, q.answer_kind, q.options);
    insert into public.game_session_sides(session_id, actor_role)
      values(sid, 'francesco'), (sid, 'beatrice');
  end if;
  return private.m11a_session_state(sid, actor.caller_couple, actor.caller_role);
end;
$function$;

-- public.start_game_round(target_family text, request_id uuid)
CREATE OR REPLACE FUNCTION public.start_game_round(target_family text, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; sid uuid; existing_family text; at_time timestamptz := private.game_v2_clock();
  ordinal integer; heavy text; items jsonb; e jsonb; pos integer := 0; subject text;
  sources text[]; source_kind text; usage jsonb;
begin
  select * into actor from private.m11a_actor_locked();
  if request_id is null then raise exception using errcode = '22023', message = 'request id required'; end if;
  if target_family is null or not (target_family = 'per_voi' or target_family = any (private.game_v2_families())) then
    raise exception using errcode = '22023', message = 'invalid family';
  end if;

  -- Replay of an earlier request: always the original round, whatever the
  -- allowance or the week is now.
  select s.id, s.game_family into sid, existing_family from public.game_sessions s
    where s.couple_id = actor.caller_couple and s.started_by_role = actor.caller_role
      and s.create_request_id = start_game_round.request_id;
  if sid is not null then
    if existing_family is distinct from target_family then
      raise exception using errcode = '22023', message = 'request already used';
    end if;
    return private.m11a_session_state(sid, actor.caller_couple, actor.caller_role) || jsonb_build_object('resumed', true);
  end if;

  perform pg_advisory_xact_lock(hashtextextended('game_v2_round:' || actor.caller_couple::text || ':' || target_family, 0));
  select s.id into sid from public.game_sessions s
    where s.couple_id = actor.caller_couple and s.started_by_role = actor.caller_role
      and s.create_request_id = start_game_round.request_id and s.game_family = target_family;
  if sid is not null then
    return private.m11a_session_state(sid, actor.caller_couple, actor.caller_role) || jsonb_build_object('resumed', true);
  end if;
  -- An open round of the same mode (from this week or an earlier one) is
  -- resumed and spends nothing.
  select s.id into sid from public.game_sessions s
    where s.couple_id = actor.caller_couple and s.engine_version = 2 and s.game_family = target_family
      and s.completed_at is null;
  if sid is not null then
    return private.m11a_session_state(sid, actor.caller_couple, actor.caller_role) || jsonb_build_object('resumed', true);
  end if;

  -- Weekly budget. Taken after the per-mode lock on every path, so the lock
  -- order is fixed; usage is read again under it (READ COMMITTED: a new
  -- snapshot per statement sees a concurrent start that just committed).
  perform pg_advisory_xact_lock(hashtextextended('game_v2_budget:' || actor.caller_couple::text, 0));
  usage := private.game_v2_week_usage(actor.caller_couple, at_time);
  if target_family = 'per_voi' and not (usage->>'per_voi_available')::boolean then
    raise exception using errcode = 'P0001', message = 'weekly per voi played',
      detail = 'resets_on=' || (usage->>'resets_on');
  end if;
  if target_family <> 'per_voi' and not (usage->>'free_available')::boolean then
    raise exception using errcode = 'P0001', message = 'weekly allowance exhausted',
      detail = 'resets_on=' || (usage->>'resets_on');
  end if;
  if (usage->>'open_count')::integer >= (usage->>'open_limit')::integer then
    raise exception using errcode = 'P0001', message = 'too many open rounds';
  end if;

  select count(*) into ordinal from public.game_sessions s
    where s.couple_id = actor.caller_couple and s.engine_version = 2;
  select case when count(*) % 2 = 0 then 'beatrice' else 'francesco' end into heavy
    from public.game_sessions s
    where s.couple_id = actor.caller_couple and s.engine_version = 2 and s.subject_heavy_role is not null;

  items := private.game_v2_select_items(actor.caller_couple, target_family, at_time, ordinal);
  if jsonb_array_length(items) < 5 then
    raise exception using errcode = 'P0001', message = 'not enough content';
  end if;
  items := private.game_v2_assign_subjects(actor.caller_couple, items, heavy);
  select array_agg(distinct x->>'source_type' order by x->>'source_type') into sources from jsonb_array_elements(items) x;
  source_kind := case when sources = array['curated'] then 'curated'
    when sources = array['couple_custom'] then 'couple_custom' else 'mixed' end;

  -- started_at follows the server clock: it is what the weekly usage counts.
  insert into public.game_sessions(couple_id, game_family, content_source, started_by_role, create_request_id,
    engine_version, subject_heavy_role, started_at)
  values (actor.caller_couple, target_family, source_kind, actor.caller_role, start_game_round.request_id, 2,
    case when exists (select 1 from jsonb_array_elements(items) x where x->>'mechanic' = 'prediction') then heavy end,
    at_time)
  returning id into sid;

  for e in select value from jsonb_array_elements(items) loop
    pos := pos + 1;
    subject := e->>'subject_role';
    insert into public.game_session_items(session_id, position, source_question_id, source_version,
      question_text, answer_kind, options, mechanic, subject_role, predict_text, family, source_type,
      source_ref, recipe_id, recipe_version, topic, perspective, depth, fingerprint, context)
    values (sid, pos, (e->>'source_question_id')::uuid, (e->>'source_version')::integer,
      private.game_v2_render(e->>'question_text', subject), e->>'answer_kind',
      private.game_v2_render_options(e->'options', subject), e->>'mechanic', subject,
      case when subject is not null then private.game_v2_render(e->>'predict_text', subject) end,
      e->>'family', e->>'source_type', e->>'source_ref', e->>'recipe_id', (e->>'recipe_version')::integer,
      e->>'topic', coalesce('subject:' || subject, 'mutual'), (e->>'depth')::smallint, e->>'candidate_key',
      coalesce(e->'context', '{}'::jsonb));
  end loop;
  insert into public.game_session_sides(session_id, actor_role) values (sid, 'francesco'), (sid, 'beatrice');
  return private.m11a_session_state(sid, actor.caller_couple, actor.caller_role) || jsonb_build_object('resumed', false);
end;
$function$;

-- public.start_swipe_round(request_id uuid)
CREATE OR REPLACE FUNCTION public.start_swipe_round(request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor record;
  sid uuid;
  existing_family text;
  at_time timestamptz := private.game_v2_clock();
  usage jsonb;
  ordinal integer;
  cards jsonb;
  card jsonb;
  pos integer := 0;
begin
  select * into actor from private.m11a_actor_locked();

  if request_id is null then
    raise exception using errcode = '22023', message = 'request id required';
  end if;

  -- Idempotent replay wins even if the weekly allowance is now spent.
  select s.id, s.game_family into sid, existing_family
  from public.game_sessions s
  where s.couple_id = actor.caller_couple
    and s.started_by_role = actor.caller_role
    and s.create_request_id = start_swipe_round.request_id;

  if sid is not null then
    if existing_family is distinct from 'swipe' then
      raise exception using errcode = '22023', message = 'request already used';
    end if;
    return private.m11a_session_state(sid, actor.caller_couple, actor.caller_role)
      || jsonb_build_object('resumed', true);
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('game_v2_round:' || actor.caller_couple::text || ':swipe', 0)
  );

  -- One canonical open Swipe round for the couple.
  select s.id into sid
  from public.game_sessions s
  where s.couple_id = actor.caller_couple
    and s.engine_version = 2
    and s.game_family = 'swipe'
    and s.completed_at is null;

  if sid is not null then
    return private.m11a_session_state(sid, actor.caller_couple, actor.caller_role)
      || jsonb_build_object('resumed', true);
  end if;

  -- Swipe spends one of the same two weekly free-choice moments as the
  -- existing six modes. Resuming an older open Swipe spends nothing.
  perform pg_advisory_xact_lock(
    hashtextextended('game_v2_budget:' || actor.caller_couple::text, 0)
  );
  usage := private.game_v2_week_usage(actor.caller_couple, at_time);

  if not (usage->>'free_available')::boolean then
    raise exception using errcode = 'P0001', message = 'weekly allowance exhausted',
      detail = 'resets_on=' || (usage->>'resets_on');
  end if;

  if (usage->>'open_count')::integer >= (usage->>'open_limit')::integer then
    raise exception using errcode = 'P0001', message = 'too many open rounds';
  end if;

  select count(*)::integer into ordinal
  from public.game_sessions s
  where s.couple_id = actor.caller_couple and s.engine_version = 2;

  -- Prefer cards this couple has never seen, then the least-recently played.
  -- md5 gives a deterministic shuffle inside each recency bucket.
  select coalesce(jsonb_agg(to_jsonb(picked) - 'last_played' - 'sort_key' order by picked.pick_order), '[]'::jsonb)
  into cards
  from (
    select ranked.*, row_number() over (
      order by ranked.last_played asc nulls first, ranked.sort_key
    ) as pick_order
    from (
      select c.id, c.version, c.question_text, c.options, c.topic,
        (
          select max(s.started_at)
          from public.game_session_items i
          join public.game_sessions s on s.id = i.session_id
          where s.couple_id = actor.caller_couple
            and i.fingerprint = ('swipe:' || c.id || ':v' || c.version::text)
        ) as last_played,
        md5(
          c.id || ':' || actor.caller_couple::text || ':' ||
          private.game_v2_week_start(at_time)::text || ':' || ordinal::text
        ) as sort_key
      from private.game_swipe_v1_catalog c
      where c.active
    ) ranked
    order by ranked.last_played asc nulls first, ranked.sort_key
    limit 8
  ) picked;

  if jsonb_array_length(cards) <> 8 then
    raise exception using errcode = 'P0001', message = 'not enough swipe content';
  end if;

  insert into public.game_sessions (
    couple_id, game_family, content_source, started_by_role, create_request_id,
    engine_version, started_at
  )
  values (
    actor.caller_couple, 'swipe', 'curated', actor.caller_role,
    start_swipe_round.request_id, 2, at_time
  )
  returning id into sid;

  for card in select value from jsonb_array_elements(cards) loop
    pos := pos + 1;
    insert into public.game_session_items (
      session_id, position, source_question_id, source_version,
      question_text, answer_kind, options, mechanic, subject_role, predict_text,
      family, source_type, source_ref, recipe_id, recipe_version, topic,
      perspective, depth, fingerprint, context
    )
    values (
      sid, pos, null, (card->>'version')::integer,
      card->>'question_text', 'choice', card->'options', 'reciprocal', null, null,
      null, 'curated', 'swipe:' || (card->>'id'), null, null, card->>'topic',
      'mutual', 1, 'swipe:' || (card->>'id') || ':v' || (card->>'version'),
      jsonb_build_object('swipe_v1', true)
    );
  end loop;

  insert into public.game_session_sides(session_id, actor_role)
  values (sid, 'francesco'), (sid, 'beatrice');

  return private.m11a_session_state(sid, actor.caller_couple, actor.caller_role)
    || jsonb_build_object('resumed', false);
end;
$function$;

-- public.update_couple_question(target_question_id uuid, expected_version integer, question_text text, answer_kind text, options jsonb)
CREATE OR REPLACE FUNCTION public.update_couple_question(target_question_id uuid, expected_version integer, question_text text, answer_kind text, options jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor record; normalized jsonb; q public.couple_questions%rowtype;
begin
  select * into actor from private.m11a_actor_locked();
  normalized := private.m11a_valid_options(answer_kind, question_text, options);
  select * into q from public.couple_questions
    where id = target_question_id and couple_id = actor.caller_couple for update;
  if q.id is null then raise exception using errcode = '42501', message = 'question unavailable'; end if;
  if q.author_role <> actor.caller_role then raise exception using errcode = '42501', message = 'author only'; end if;
  if q.archived_at is not null then raise exception using errcode = '22023', message = 'question archived'; end if;
  if expected_version is distinct from q.version then raise exception using errcode = '40001', message = 'version conflict'; end if;
  update public.couple_questions set question_text = btrim(update_couple_question.question_text),
    answer_kind = update_couple_question.answer_kind, options = normalized,
    version = version + 1, updated_at = now() where id = q.id returning * into q;
  return private.m11a_question_json(q);
end;
$function$;
comment on function public.update_couple_question(target_question_id uuid, expected_version integer, question_text text, answer_kind text, options jsonb) is 'RETIRED (US 2.0 F1B): M11A, superseded by Game V2. EXECUTE revoked from public/anon/authenticated.';

-- public.widget_scriptable_exchange_internal(p_setup_token_hash text, p_device_id_hash text, p_state_token_hash text, p_action_token_hash text)
CREATE OR REPLACE FUNCTION public.widget_scriptable_exchange_internal(p_setup_token_hash text, p_device_id_hash text, p_state_token_hash text, p_action_token_hash text)
 RETURNS TABLE(installation_id uuid, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  setup_code public.widget_scriptable_setup_codes%rowtype;
  setup_profile_id uuid;
  current_profile_couple_id uuid;
  action_token_id uuid;
  new_installation_id uuid;
  action_expiry timestamptz := now() + interval '180 days';
begin
  if p_setup_token_hash !~ '^[a-f0-9]{64}$'
     or p_device_id_hash !~ '^[a-f0-9]{64}$'
     or p_state_token_hash !~ '^[a-f0-9]{64}$'
     or p_action_token_hash !~ '^[a-f0-9]{64}$' then
    raise exception using errcode = '22023', message = 'invalid_setup_request';
  end if;

  select code.profile_id into setup_profile_id
  from public.widget_scriptable_setup_codes as code
  where code.token_hash = p_setup_token_hash;
  if setup_profile_id is null then
    raise exception using errcode = '28000', message = 'invalid_or_expired_setup_code';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(1, pg_catalog.hashtext(p_device_id_hash));
  perform pg_catalog.pg_advisory_xact_lock(0, pg_catalog.hashtext(setup_profile_id::text));

  select code.* into setup_code
  from public.widget_scriptable_setup_codes as code
  where code.token_hash = p_setup_token_hash
    and code.consumed_at is null
    and code.revoked_at is null
    and code.expires_at > now()
  for update;

  if setup_code.id is null then
    raise exception using errcode = '28000', message = 'invalid_or_expired_setup_code';
  end if;

  select profile.couple_id
  into current_profile_couple_id
  from public.profiles as profile
  where profile.id = setup_code.profile_id
  for update;

  if not found or current_profile_couple_id is distinct from setup_code.couple_id then
    raise exception using errcode = '28000', message = 'widget_profile_not_linked';
  end if;

  update public.widget_scriptable_installations as old_installation
  set revoked_at = now()
  where old_installation.profile_id = setup_code.profile_id
    and old_installation.couple_id = setup_code.couple_id
    and old_installation.device_id_hash = p_device_id_hash
    and old_installation.revoked_at is null;

  update public.widget_tokens as state_token
  set revoked_at = now()
  where state_token.token_hash in (
    select old_installation.state_token_hash
    from public.widget_scriptable_installations as old_installation
    where old_installation.profile_id = setup_code.profile_id
      and old_installation.couple_id = setup_code.couple_id
      and old_installation.device_id_hash = p_device_id_hash
      and old_installation.revoked_at is not null
  )
    and state_token.revoked_at is null;

  update public.widget_action_tokens as action_token
  set revoked_at = now()
  where action_token.id in (
    select old_installation.action_token_id
    from public.widget_scriptable_installations as old_installation
    where old_installation.profile_id = setup_code.profile_id
      and old_installation.couple_id = setup_code.couple_id
      and old_installation.device_id_hash = p_device_id_hash
      and old_installation.revoked_at is not null
  )
    and action_token.revoked_at is null;

  insert into public.widget_action_tokens(
    couple_id, profile_id, device_id_hash, token_hash, scope, expires_at
  ) values (
    setup_code.couple_id, setup_code.profile_id, p_device_id_hash,
    p_action_token_hash, 'think:send', action_expiry
  ) returning id into action_token_id;

  insert into public.widget_tokens(couple_id, profile_id, device_label, token_hash)
  values (setup_code.couple_id, setup_code.profile_id, 'Scriptable', p_state_token_hash);

  insert into public.widget_scriptable_installations(
    couple_id, profile_id, device_id_hash, state_token_hash, action_token_id, expires_at
  ) values (
    setup_code.couple_id, setup_code.profile_id, p_device_id_hash,
    p_state_token_hash, action_token_id, action_expiry
  ) returning id into new_installation_id;

  update public.widget_scriptable_setup_codes as code
  set consumed_at = now()
  where code.id = setup_code.id;

  return query select new_installation_id, action_expiry;
end;
$function$;

-- public.widget_scriptable_issue_code_internal(p_profile_id uuid, p_couple_id uuid, p_token_hash text, p_expires_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.widget_scriptable_issue_code_internal(p_profile_id uuid, p_couple_id uuid, p_token_hash text, p_expires_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from public.profiles as profile
    where profile.id = p_profile_id and profile.couple_id = p_couple_id
  ) then
    raise exception using errcode = '28000', message = 'widget_profile_not_linked';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(0, pg_catalog.hashtext(p_profile_id::text));
  if p_token_hash !~ '^[a-f0-9]{64}$' or p_expires_at <= now() or p_expires_at > now() + interval '15 minutes' then
    raise exception using errcode = '22023', message = 'invalid_setup_code';
  end if;

  update public.widget_scriptable_setup_codes as setup_code
  set revoked_at = now()
  where setup_code.profile_id = p_profile_id
    and setup_code.consumed_at is null
    and setup_code.revoked_at is null;

  insert into public.widget_scriptable_setup_codes(couple_id, profile_id, token_hash, expires_at)
  values (p_couple_id, p_profile_id, p_token_hash, p_expires_at);
end;
$function$;

-- public.widget_scriptable_revoke_internal(p_profile_id uuid)
CREATE OR REPLACE FUNCTION public.widget_scriptable_revoke_internal(p_profile_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  revoked_count integer;
begin
  perform pg_catalog.pg_advisory_xact_lock(0, pg_catalog.hashtext(p_profile_id::text));
  update public.widget_scriptable_installations as installation
  set revoked_at = now()
  where installation.profile_id = p_profile_id
    and installation.revoked_at is null;
  get diagnostics revoked_count = row_count;

  update public.widget_tokens as state_token
  set revoked_at = now()
  where state_token.token_hash in (
    select installation.state_token_hash
    from public.widget_scriptable_installations as installation
    where installation.profile_id = p_profile_id
      and installation.revoked_at is not null
  )
    and state_token.revoked_at is null;

  update public.widget_action_tokens as action_token
  set revoked_at = now()
  where action_token.id in (
    select installation.action_token_id
    from public.widget_scriptable_installations as installation
    where installation.profile_id = p_profile_id
      and installation.revoked_at is not null
  )
    and action_token.revoked_at is null;

  update public.widget_scriptable_setup_codes as setup_code
  set revoked_at = now()
  where setup_code.profile_id = p_profile_id
    and setup_code.consumed_at is null
    and setup_code.revoked_at is null;

  return revoked_count;
end;
$function$;

-- public.widget_send_think_internal(p_token_hash text, p_action_id uuid)
CREATE OR REPLACE FUNCTION public.widget_send_think_internal(p_token_hash text, p_action_id uuid)
 RETURNS TABLE(message_id uuid, sender_id uuid, recipient_id uuid, couple_id uuid, duplicate boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  credential public.widget_action_tokens%rowtype;
  receipt public.widget_action_receipts%rowtype;
  partner_id uuid;
  created_message_id uuid;
begin
  select token.* into credential
  from public.widget_action_tokens as token
  where token.token_hash = p_token_hash
    and token.scope = 'think:send'
    and token.revoked_at is null
    and token.expires_at > now()
  for update;

  if credential.id is null then
    raise exception using errcode = '28000', message = 'invalid_widget_credential';
  end if;

  select existing_receipt.* into receipt
  from public.widget_action_receipts as existing_receipt
  where existing_receipt.token_id = credential.id
    and existing_receipt.action_id = p_action_id;

  if receipt.id is not null then
    if receipt.status = 'sent' and receipt.message_id is not null then
      select message.recipient_id into partner_id
      from public.shared_messages as message
      where message.id = receipt.message_id;

      return query select receipt.message_id, credential.profile_id, partner_id,
        credential.couple_id, true;
      return;
    end if;

    raise exception using errcode = '55000', message = 'widget_action_in_progress';
  end if;

  if credential.last_action_at is not null
     and credential.last_action_at > now() - interval '2500 milliseconds' then
    raise exception using errcode = 'P0001', message = 'widget_action_rate_limited';
  end if;

  select partner.id into partner_id
  from public.profiles as partner
  where partner.couple_id = credential.couple_id
    and partner.id <> credential.profile_id
  order by partner.created_at, partner.id
  limit 1;

  if partner_id is null then
    raise exception using errcode = 'P0001', message = 'widget_partner_missing';
  end if;

  insert into public.widget_action_receipts(token_id, action_id, action_type, status)
  values (credential.id, p_action_id, 'think:send', 'processing');

  insert into public.shared_messages(
    couple_id, sender_id, recipient_id, kind, body, think_operation_id
  )
  values (
    credential.couple_id, credential.profile_id, partner_id,
    'think', 'Ti penso', p_action_id
  )
  returning id into created_message_id;

  update public.widget_action_receipts as action_receipt
  set status = 'sent', message_id = created_message_id, completed_at = now()
  where action_receipt.token_id = credential.id
    and action_receipt.action_id = p_action_id;

  update public.widget_action_tokens as action_token
  set last_used_at = now(), last_action_at = now()
  where action_token.id = credential.id;

  return query select created_message_id, credential.profile_id, partner_id,
    credential.couple_id, false;
end;
$function$;
